class Solution:
    def findLucky(self, arr: List[int]) -> int:
        cnt = Counter(arr)
        heap = []
        for k,v in cnt.items():
            if k == v:
                heapq.heappush(heap, (v, k))

            if len(heap) > 1:
                heapq.heappop(heap)
        if not heap:
            return -1
        return heap[0][1]
